1	import { ed25519 } from "@noble/curves/ed25519.js";
2	import { compareBytes, decodeCanonical, encodeCanonical, hashDomain } from "@ts-drp/canonical";
3	
4	import type { CurrentAnchorTrust } from "./index.js";
5	import {
6		type CreatorIssuanceRetirementSigningRequest,
7		mintCreatorIssuanceRetirementSigningRequest,
8	} from "./internal/creator-issuance-retirement-signing-request.js";
9	import { resolveCreatorAnchorTrustMaterial } from "./internal/seal-authority-custody.js";
10	import { settlementProfileFor } from "./settlement-profile.js";
11	
12	export const CREATOR_AUTHOR_ISSUANCE_FRONTIERS_KIND = "drp-creator-author-issuance-frontiers-state" as const;
13	export const CREATOR_AUTHOR_ISSUANCE_FRONTIERS_MAX_RECORD_BYTES = 8192 as const;
14	export const CREATOR_AUTHOR_ISSUANCE_FRONTIERS_GENESIS_SENTINEL = hex(
15		hashDomain(
16			"ts-drp/creator-author-issuance-frontiers/genesis/v1",
17			encodeCanonical({ kind: "drp-creator-author-issuance-frontiers-genesis", version: 1 })
18		)
19	);
20	
21	const DOMAIN = "ts-drp/creator-author-issuance-frontiers/v1";
22	const DIGEST = /^[0-9a-f]{64}$/u;
23	const OBJECT_ID = /^[A-Za-z0-9._:-]{1,256}$/u;
24	const PREIMAGE_KEYS = Object.freeze([
25		"closedAnchorDigest",
26		"closedEpoch",
27		"commitQcRef",
28		"currentAclDigest",
29		"cutValueDigest",
30		"frontiers",
31		"genesisAnchorDigest",
32		"kind",
33		"objectId",
34		"priorAggregateCandidateDigest",
35		"protocolMajor",
36		"snapshotManifestDigest",
37		"successorAclDigest",
38		"successorAnchorDigest",
39		"successorEpoch",
40		"version",
41	] as const);
42	const RECORD_KEYS = Object.freeze([...PREIMAGE_KEYS, "detachedCreatorSignature"] as const);
43	const OPEN_KEYS = Object.freeze([
44		"exactCanonicalRecordBytes",
45		"expectedCommitQcRef",
46		"expectedCurrentAclDigest",
47		"expectedCutValueDigest",
48		"expectedSnapshotManifestDigest",
49		"expectedSuccessorAclDigest",
50		"floorTrust",
51	] as const);
52	const OPEN_KEYS_WITH_CURRENT = Object.freeze([...OPEN_KEYS, "currentTrust"] as const);
53	const PREPARE_KEYS = Object.freeze([
54		"commitQcRef",
55		"currentAclDigest",
56		"currentTrust",
57		"cutValueDigest",
58		"frontiers",
59		"priorAggregateCandidateDigest",
60		"snapshotManifestDigest",
61		"successorAclDigest",
62		"successorTrust",
63	] as const);
