65	export type CreatorAuthorIssuanceFrontier = readonly [author: string, admittedAuthorSequence: number | null];
66	
67	export interface CreatorAuthorIssuanceFrontiersRef {
68		readonly byteLength: number;
69		readonly digest: string;
70	}
71	
72	export interface CreatorAuthorIssuanceFrontiersIdentity {
73		readonly closedAnchorDigest: string;
74		readonly closedEpoch: number;
75		readonly commitQcRef: CreatorAuthorIssuanceFrontiersRef;
76		readonly currentAclDigest: string;
77		readonly cutValueDigest: string;
78		readonly frontiers: readonly CreatorAuthorIssuanceFrontier[];
79		readonly genesisAnchorDigest: string;
80		readonly objectId: string;
81		readonly priorAggregateCandidateDigest: string;
82		readonly snapshotManifestDigest: string;
83		readonly successorAclDigest: string;
84		readonly successorAnchorDigest: string;
85		readonly successorEpoch: number;
86	}
87	
88	export interface CreatorAuthorIssuanceFrontiersPreparation {
89		readonly __creatorAuthorIssuanceFrontiersPreparation?: never;
90	}
91	
92	export interface VerifiedCreatorAuthorIssuanceFrontiers {
93		readonly __verifiedCreatorAuthorIssuanceFrontiers?: never;
94	}
95	
96	interface PreparationState {
97		readonly digest: Uint8Array;
98		readonly preimage: Readonly<Record<string, unknown>>;
99		readonly publicKey: Uint8Array;
100	}
101	
102	const preparations = new WeakMap<CreatorAuthorIssuanceFrontiersPreparation, PreparationState>();
103	const verified = new WeakMap<VerifiedCreatorAuthorIssuanceFrontiers, CreatorAuthorIssuanceFrontiersIdentity>();
104	
105	function hex(bytes: Uint8Array): string {
106		return Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("");
107	}
108	
109	function plainRecord(value: unknown): value is Readonly<Record<string, unknown>> {
110		if (value === null || typeof value !== "object" || Array.isArray(value)) return false;
111		const prototype = Object.getPrototypeOf(value);
112		return prototype === Object.prototype || prototype === null;
113	}
114	
115	function exactKeys(value: Readonly<Record<string, unknown>>, keys: readonly string[]): boolean {
116		const actual = Reflect.ownKeys(value);
117		return (
118			actual.length === keys.length &&
119			actual.every((key) => typeof key === "string" && keys.includes(key)) &&
120			keys.every((key) => {
121				const descriptor = Object.getOwnPropertyDescriptor(value, key);
122				return descriptor?.enumerable === true && "value" in descriptor;
123			})
124		);
125	}
126	
127	function safeSequence(value: unknown): value is number {
128		return typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
129	}
130	
131	function anchorAclDigest(exactCanonicalAnchorPreimageBytes: Uint8Array): string | undefined {
132		try {
133			const decoded = decodeCanonical(exactCanonicalAnchorPreimageBytes);
134			return plainRecord(decoded) && typeof decoded.aclDigest === "string" && DIGEST.test(decoded.aclDigest)
135				? decoded.aclDigest
136				: undefined;
137		} catch {
138			return undefined;
139		}
140	}
141	
142	function validRef(value: unknown): value is CreatorAuthorIssuanceFrontiersRef {
143		return (
144			plainRecord(value) &&
145			exactKeys(value, ["byteLength", "digest"]) &&
146			typeof value.byteLength === "number" &&
147			Number.isSafeInteger(value.byteLength) &&
148			value.byteLength > 0 &&
149			typeof value.digest === "string" &&
150			DIGEST.test(value.digest)
151		);
152	}
153	
154	function exactFrontier(value: unknown): CreatorAuthorIssuanceFrontier | undefined {
155		if (!Array.isArray(value) || Object.getPrototypeOf(value) !== Array.prototype || value.length !== 2) return undefined;
156		const keys = Reflect.ownKeys(value);
157		if (keys.length !== 3 || !keys.includes("0") || !keys.includes("1") || !keys.includes("length")) return undefined;
158		const author = value[0];
159		const sequence = value[1];
160		return typeof author === "string" && DIGEST.test(author) && (sequence === null || safeSequence(sequence))
161			? Object.freeze([author, sequence] as const)
162			: undefined;
163	}
164	
165	function copiedFrontiers(value: unknown): readonly CreatorAuthorIssuanceFrontier[] | undefined {
166		if (!Array.isArray(value) || Object.getPrototypeOf(value) !== Array.prototype || value.length > 64) {
167			return undefined;
168		}
169		const keys = Reflect.ownKeys(value);
170		if (
171			keys.length !== value.length + 1 ||
172			!keys.includes("length") ||
173			value.some((_entry, index) => !keys.includes(String(index)))
174		) {
175			return undefined;
176		}
177		const output: CreatorAuthorIssuanceFrontier[] = [];
178		let previous = "";
179		for (const entry of value) {
180			const selected = exactFrontier(entry);
181			if (selected === undefined || selected[0] <= previous) return undefined;
182			previous = selected[0];
183			output.push(selected);
184		}
185		return Object.freeze(output);
186	}
187	
188	function validRecordFields(record: Readonly<Record<string, unknown>>): boolean {
189		return (
190			record.kind === CREATOR_AUTHOR_ISSUANCE_FRONTIERS_KIND &&
191			record.protocolMajor === 3 &&
192			record.version === 1 &&
193			typeof record.objectId === "string" &&
194			OBJECT_ID.test(record.objectId) &&
195			typeof record.genesisAnchorDigest === "string" &&
196			DIGEST.test(record.genesisAnchorDigest) &&
197			safeSequence(record.closedEpoch) &&
198			typeof record.closedAnchorDigest === "string" &&
199			DIGEST.test(record.closedAnchorDigest) &&
200			safeSequence(record.successorEpoch) &&
201			record.successorEpoch === record.closedEpoch + 1 &&
202			typeof record.successorAnchorDigest === "string" &&
203			DIGEST.test(record.successorAnchorDigest) &&
204			typeof record.currentAclDigest === "string" &&
205			DIGEST.test(record.currentAclDigest) &&
206			typeof record.successorAclDigest === "string" &&
207			DIGEST.test(record.successorAclDigest) &&
208			typeof record.cutValueDigest === "string" &&
209			DIGEST.test(record.cutValueDigest) &&
210			validRef(record.commitQcRef) &&
211			typeof record.snapshotManifestDigest === "string" &&
212			DIGEST.test(record.snapshotManifestDigest) &&
213			typeof record.priorAggregateCandidateDigest === "string" &&
214			DIGEST.test(record.priorAggregateCandidateDigest) &&
215			copiedFrontiers(record.frontiers) !== undefined
216		);
217	}
218	
219	function identity(record: Readonly<Record<string, unknown>>): CreatorAuthorIssuanceFrontiersIdentity {
220		const ref = record.commitQcRef as CreatorAuthorIssuanceFrontiersRef;
221		return Object.freeze({
222			closedAnchorDigest: record.closedAnchorDigest as string,
223			closedEpoch: record.closedEpoch as number,
224			commitQcRef: Object.freeze({ byteLength: ref.byteLength, digest: ref.digest }),
225			currentAclDigest: record.currentAclDigest as string,
226			cutValueDigest: record.cutValueDigest as string,
227			frontiers: copiedFrontiers(record.frontiers) as readonly CreatorAuthorIssuanceFrontier[],
228			genesisAnchorDigest: record.genesisAnchorDigest as string,
229			objectId: record.objectId as string,
230			priorAggregateCandidateDigest: record.priorAggregateCandidateDigest as string,
231			snapshotManifestDigest: record.snapshotManifestDigest as string,
232			successorAclDigest: record.successorAclDigest as string,
233			successorAnchorDigest: record.successorAnchorDigest as string,
234			successorEpoch: record.successorEpoch as number,
235		});
236	}
237	
238	function copiedIdentity(value: CreatorAuthorIssuanceFrontiersIdentity): CreatorAuthorIssuanceFrontiersIdentity {
239		return Object.freeze({
240			...value,
241			commitQcRef: Object.freeze({ ...value.commitQcRef }),
242			frontiers: Object.freeze(
243				value.frontiers.map((entry) => Object.freeze([...entry]) as CreatorAuthorIssuanceFrontier)
244			),
245		});
246	}
247	
248	function failure(reason: string): Readonly<{ ok: false; reason: string }> {
249		return Object.freeze({ ok: false as const, reason });
250	}
251	
252	/**
253	 * Prepares one creator-signed bounded current-writer issuance frontier.
254	 * @param input - Authenticated adjacent trust floors and exact close identities.
255	 * @returns One-use signing preparation or a closed failure.
256	 */
257	export function prepareCreatorAuthorIssuanceFrontiers(input: unknown): Readonly<
258		| { ok: false; reason: string }
259		| {
260				digest: string;
261				exactCanonicalPreimageBytes: Uint8Array;
262				ok: true;
263				preparation: CreatorAuthorIssuanceFrontiersPreparation;
264				signingRequest: CreatorIssuanceRetirementSigningRequest;
265		  }
266	> {
267		try {
268			if (!plainRecord(input) || !exactKeys(input, PREPARE_KEYS)) return failure("MALFORMED_INPUT");
269			const current = resolveCreatorAnchorTrustMaterial(input.currentTrust as CurrentAnchorTrust);
270			const successor = resolveCreatorAnchorTrustMaterial(input.successorTrust as CurrentAnchorTrust);
271			const frontiers = copiedFrontiers(input.frontiers);
272			if (
273				current === undefined ||
274				successor === undefined ||
275				frontiers === undefined ||
276				current.objectId !== successor.objectId ||
277				current.genesisAnchorDigest !== successor.genesisAnchorDigest ||
278				successor.currentEpoch !== current.currentEpoch + 1 ||
279				compareBytes(current.publicKey, successor.publicKey) !== 0 ||
280				input.currentAclDigest !== anchorAclDigest(current.exactCanonicalCurrentAnchorPreimageBytes) ||
281				input.successorAclDigest !== anchorAclDigest(successor.exactCanonicalCurrentAnchorPreimageBytes)
282			) {
283				return failure("TRUST_INVALID");
284			}
285			const preimage = Object.freeze({
286				closedAnchorDigest: current.currentAnchorDigest,
287				closedEpoch: current.currentEpoch,
288				commitQcRef: plainRecord(input.commitQcRef)
289					? Object.freeze({ byteLength: input.commitQcRef.byteLength, digest: input.commitQcRef.digest })
290					: input.commitQcRef,
291				currentAclDigest: input.currentAclDigest,
292				cutValueDigest: input.cutValueDigest,
293				frontiers,
294				genesisAnchorDigest: current.genesisAnchorDigest,
295				kind: CREATOR_AUTHOR_ISSUANCE_FRONTIERS_KIND,
296				objectId: current.objectId,
297				priorAggregateCandidateDigest: input.priorAggregateCandidateDigest,
298				protocolMajor: 3,
299				snapshotManifestDigest: input.snapshotManifestDigest,
300				successorAclDigest: input.successorAclDigest,
301				successorAnchorDigest: successor.currentAnchorDigest,
302				successorEpoch: successor.currentEpoch,
303				version: 1,
304			});
305			if (!validRecordFields(preimage)) return failure("IDENTITY_INVALID");
306			const exactCanonicalPreimageBytes = encodeCanonical(preimage);
307			const digest = hashDomain(DOMAIN, exactCanonicalPreimageBytes);
308			const preparation = Object.freeze({}) as CreatorAuthorIssuanceFrontiersPreparation;
309			preparations.set(
310				preparation,
311				Object.freeze({ digest: Uint8Array.from(digest), preimage, publicKey: Uint8Array.from(current.publicKey) })
312			);
313			return Object.freeze({
314				digest: hex(digest),
315				exactCanonicalPreimageBytes: Uint8Array.from(exactCanonicalPreimageBytes),
316				ok: true as const,
317				preparation,
318				signingRequest: mintCreatorIssuanceRetirementSigningRequest(digest),
319			});
320		} catch {
321			return failure("MALFORMED_INPUT");
322		}
323	}
