325	/**
326	 * Completes and size-bounds one prepared frontier record.
327	 * @param input - Opaque preparation and detached creator signature.
328	 * @returns Exact canonical record bytes or a closed failure.
329	 */
330	export function completeCreatorAuthorIssuanceFrontiers(
331		input: unknown
332	): Readonly<{ exactCanonicalRecordBytes: Uint8Array; ok: true } | { ok: false; reason: string }> {
333		try {
334			if (!plainRecord(input) || !exactKeys(input, ["detachedSignature", "preparation"])) {
335				return failure("MALFORMED_INPUT");
336			}
337			const state = preparations.get(input.preparation as CreatorAuthorIssuanceFrontiersPreparation);
338			preparations.delete(input.preparation as CreatorAuthorIssuanceFrontiersPreparation);
339			if (state === undefined) return failure("PREPARATION_UNAVAILABLE");
340			if (!(input.detachedSignature instanceof Uint8Array) || input.detachedSignature.byteLength !== 64) {
341				return failure("SIGNATURE_INVALID");
342			}
343			const signature = Uint8Array.from(input.detachedSignature);
344			if (!ed25519.verify(signature, state.digest, state.publicKey, { zip215: false })) {
345				return failure("SIGNATURE_INVALID");
346			}
347			const exactCanonicalRecordBytes = encodeCanonical({
348				...state.preimage,
349				detachedCreatorSignature: signature,
350			});
351			return exactCanonicalRecordBytes.byteLength > CREATOR_AUTHOR_ISSUANCE_FRONTIERS_MAX_RECORD_BYTES
352				? failure("RECORD_TOO_LARGE")
353				: Object.freeze({ exactCanonicalRecordBytes: Uint8Array.from(exactCanonicalRecordBytes), ok: true as const });
354		} catch {
355			return failure("MALFORMED_INPUT");
356		}
357	}
