359	/**
360	 * Opens one exact frontier record against an independently authenticated successor floor.
361	 * @param input - Exact record, close identities, and authenticated successor floor.
362	 * @returns Opaque verified capability or a closed failure.
363	 */
364	export function openCreatorAuthorIssuanceFrontiers(
365		input: unknown
366	): Readonly<{ capability: VerifiedCreatorAuthorIssuanceFrontiers; ok: true } | { ok: false; reason: string }> {
367		try {
368			if (
369				!plainRecord(input) ||
370				(!exactKeys(input, OPEN_KEYS) && !exactKeys(input, OPEN_KEYS_WITH_CURRENT)) ||
371				!(input.exactCanonicalRecordBytes instanceof Uint8Array) ||
372				input.exactCanonicalRecordBytes.byteLength > CREATOR_AUTHOR_ISSUANCE_FRONTIERS_MAX_RECORD_BYTES
373			) {
374				return failure("MALFORMED_INPUT");
375			}
376			const bytes = Uint8Array.from(input.exactCanonicalRecordBytes);
377			const decoded = decodeCanonical(bytes, { maxBytes: CREATOR_AUTHOR_ISSUANCE_FRONTIERS_MAX_RECORD_BYTES });
378			if (
379				!plainRecord(decoded) ||
380				!exactKeys(decoded, RECORD_KEYS) ||
381				compareBytes(encodeCanonical(decoded), bytes) !== 0 ||
382				!validRecordFields(decoded) ||
383				!(decoded.detachedCreatorSignature instanceof Uint8Array)
384			) {
385				return failure("RECORD_INVALID");
386			}
387			const floor = resolveCreatorAnchorTrustMaterial(input.floorTrust as CurrentAnchorTrust);
388			const current =
389				"currentTrust" in input ? resolveCreatorAnchorTrustMaterial(input.currentTrust as CurrentAnchorTrust) : undefined;
390			const ref = decoded.commitQcRef as CreatorAuthorIssuanceFrontiersRef;
391			if (
392				floor === undefined ||
393				("currentTrust" in input && current === undefined) ||
394				(current !== undefined &&
395					(current.objectId !== floor.objectId ||
396						current.genesisAnchorDigest !== floor.genesisAnchorDigest ||
397						current.currentEpoch + 1 !== floor.currentEpoch ||
398						current.currentAnchorDigest !== decoded.closedAnchorDigest ||
399						current.currentEpoch !== decoded.closedEpoch ||
400						compareBytes(current.publicKey, floor.publicKey) !== 0 ||
401						decoded.currentAclDigest !== anchorAclDigest(current.exactCanonicalCurrentAnchorPreimageBytes))) ||
402				decoded.objectId !== floor.objectId ||
403				decoded.genesisAnchorDigest !== floor.genesisAnchorDigest ||
404				decoded.successorEpoch !== floor.currentEpoch ||
405				decoded.successorAnchorDigest !== floor.currentAnchorDigest ||
406				decoded.successorAclDigest !== anchorAclDigest(floor.exactCanonicalCurrentAnchorPreimageBytes) ||
407				decoded.currentAclDigest !== input.expectedCurrentAclDigest ||
408				decoded.successorAclDigest !== input.expectedSuccessorAclDigest ||
409				decoded.cutValueDigest !== input.expectedCutValueDigest ||
410				decoded.snapshotManifestDigest !== input.expectedSnapshotManifestDigest ||
411				!validRef(input.expectedCommitQcRef) ||
412				ref.byteLength !== input.expectedCommitQcRef.byteLength ||
413				ref.digest !== input.expectedCommitQcRef.digest
414			) {
415				return failure("IDENTITY_INVALID");
416			}
417			const { detachedCreatorSignature: signature, ...preimage } = decoded;
418			const digest = hashDomain(DOMAIN, encodeCanonical(preimage));
419			if (signature.byteLength !== 64 || !ed25519.verify(signature, digest, floor.publicKey, { zip215: false })) {
420				return failure("SIGNATURE_INVALID");
421			}
422			const capability = Object.freeze({}) as VerifiedCreatorAuthorIssuanceFrontiers;
423			verified.set(capability, identity(decoded));
424			return Object.freeze({ capability, ok: true as const });
425		} catch {
426			return failure("MALFORMED_INPUT");
427		}
428	}
