430	/**
431	 * Resolves detached verified identity from a genuine opaque frontier capability.
432	 * @param capability - Capability returned by openCreatorAuthorIssuanceFrontiers.
433	 * @returns A detached frozen identity or undefined for foreign custody.
434	 */
435	export function resolveCreatorAuthorIssuanceFrontiers(
436		capability: VerifiedCreatorAuthorIssuanceFrontiers
437	): CreatorAuthorIssuanceFrontiersIdentity | undefined {
438		const selected = verified.get(capability);
439		return selected === undefined ? undefined : copiedIdentity(selected);
440	}
