442	export const CREATOR_AUTHOR_SETTLEMENT_KIND = "drp-creator-author-settlement-state" as const;
443	export const CREATOR_AUTHOR_SETTLEMENT_MAX_RECORD_BYTES = 32_768 as const;
444	export const CREATOR_AUTHOR_SETTLEMENT_GENESIS_SENTINEL = hex(
445		hashDomain(
446			"ts-drp/creator-author-settlement/genesis/v1",
447			encodeCanonical({ kind: "drp-creator-author-settlement-genesis", version: 1 })
448		)
449	);
