451	const SETTLEMENT_DOMAIN = "ts-drp/creator-author-settlement/v1";
452	const SETTLEMENT_PREIMAGE_KEYS = Object.freeze([
453		"closedAnchorDigest",
454		"closedEpoch",
455		"commitQcRef",
456		"currentAclDigest",
457		"cutValueDigest",
458		"frontiers",
