473	const SETTLEMENT_RECORD_KEYS = Object.freeze([...SETTLEMENT_PREIMAGE_KEYS, "detachedAuthoritySignature"] as const);
474	const SETTLEMENT_PREPARE_KEYS = Object.freeze([
475		"commitQcRef",
476		"currentAclDigest",
477		"currentTrust",
