528	const settlementPreparations = new WeakMap<CreatorAuthorSettlementPreparation, SettlementPreparationState>();
529	const verifiedSettlements = new WeakMap<VerifiedCreatorAuthorSettlement, CreatorAuthorSettlementIdentity>();
