531	function exactSettlementFrontier(value: unknown): CreatorAuthorSettlementFrontier | undefined {
532		if (!Array.isArray(value) || Object.getPrototypeOf(value) !== Array.prototype || value.length !== 3) return undefined;
533		const keys = Reflect.ownKeys(value);
534		if (
535			keys.length !== 4 ||
536			!keys.includes("0") ||
537			!keys.includes("1") ||
538			!keys.includes("2") ||
539			!keys.includes("length")
540		) {
541			return undefined;
542		}
543		const [author, admissionEpoch, terminalThrough] = value;
544		return typeof author === "string" &&
545			DIGEST.test(author) &&
546			safeSequence(admissionEpoch) &&
547			(terminalThrough === null || safeSequence(terminalThrough))
548			? Object.freeze([author, admissionEpoch, terminalThrough])
549			: undefined;
550	}
551	
552	function copiedSettlementFrontiers(value: unknown): readonly CreatorAuthorSettlementFrontier[] | undefined {
553		if (!Array.isArray(value) || Object.getPrototypeOf(value) !== Array.prototype || value.length > 256) return undefined;
554		const keys = Reflect.ownKeys(value);
555		if (
556			keys.length !== value.length + 1 ||
557			!keys.includes("length") ||
558			value.some((_entry, index) => !keys.includes(String(index)))
559		) {
560			return undefined;
561		}
562		const output: CreatorAuthorSettlementFrontier[] = [];
563		let previous: string | undefined;
564		for (const entry of value) {
565			const selected = exactSettlementFrontier(entry);
566			if (selected === undefined || (previous !== undefined && selected[0] <= previous)) return undefined;
567			previous = selected[0];
568			output.push(selected);
569		}
570		return Object.freeze(output);
571	}
572	
573	function validSettlementRecordFields(record: Readonly<Record<string, unknown>>): boolean {
574		return (
575			record.kind === CREATOR_AUTHOR_SETTLEMENT_KIND &&
576			record.protocolMajor === 3 &&
577			record.version === 1 &&
578			typeof record.objectId === "string" &&
579			OBJECT_ID.test(record.objectId) &&
580			typeof record.genesisAnchorDigest === "string" &&
581			DIGEST.test(record.genesisAnchorDigest) &&
582			safeSequence(record.closedEpoch) &&
583			typeof record.closedAnchorDigest === "string" &&
584			DIGEST.test(record.closedAnchorDigest) &&
585			safeSequence(record.successorEpoch) &&
586			record.successorEpoch === record.closedEpoch + 1 &&
587			typeof record.successorAnchorDigest === "string" &&
588			DIGEST.test(record.successorAnchorDigest) &&
589			typeof record.currentAclDigest === "string" &&
590			DIGEST.test(record.currentAclDigest) &&
591			typeof record.successorAclDigest === "string" &&
592			DIGEST.test(record.successorAclDigest) &&
593			typeof record.cutValueDigest === "string" &&
594			DIGEST.test(record.cutValueDigest) &&
595			validRef(record.commitQcRef) &&
596			typeof record.snapshotManifestDigest === "string" &&
597			DIGEST.test(record.snapshotManifestDigest) &&
598			typeof record.historyRoot === "string" &&
599			DIGEST.test(record.historyRoot) &&
600			safeSequence(record.historySize) &&
601			typeof record.priorCheckpointDigest === "string" &&
602			DIGEST.test(record.priorCheckpointDigest) &&
603			(record.priorCheckpointKind === "genesis" || record.priorCheckpointKind === "settled-v1") &&
604			copiedSettlementFrontiers(record.frontiers) !== undefined
605		);
606	}
607	
608	function settlementIdentity(record: Readonly<Record<string, unknown>>): CreatorAuthorSettlementIdentity {
609		const ref = record.commitQcRef as CreatorAuthorIssuanceFrontiersRef;
610		return Object.freeze({
611			closedAnchorDigest: record.closedAnchorDigest as string,
612			closedEpoch: record.closedEpoch as number,
613			commitQcRef: Object.freeze({ byteLength: ref.byteLength, digest: ref.digest }),
614			currentAclDigest: record.currentAclDigest as string,
615			cutValueDigest: record.cutValueDigest as string,
616			frontiers: copiedSettlementFrontiers(record.frontiers) as readonly CreatorAuthorSettlementFrontier[],
617			genesisAnchorDigest: record.genesisAnchorDigest as string,
618			historyRoot: record.historyRoot as string,
619			historySize: record.historySize as number,
620			objectId: record.objectId as string,
621			priorCheckpointDigest: record.priorCheckpointDigest as string,
622			priorCheckpointKind: record.priorCheckpointKind as "genesis" | "settled-v1",
623			snapshotManifestDigest: record.snapshotManifestDigest as string,
624			successorAclDigest: record.successorAclDigest as string,
625			successorAnchorDigest: record.successorAnchorDigest as string,
626			successorEpoch: record.successorEpoch as number,
627		});
628	}
629	
630	function copiedSettlementIdentity(value: CreatorAuthorSettlementIdentity): CreatorAuthorSettlementIdentity {
631		return Object.freeze({
632			...value,
633			commitQcRef: Object.freeze({ ...value.commitQcRef }),
634			frontiers: Object.freeze(
635				value.frontiers.map((entry) => Object.freeze([...entry])) as CreatorAuthorSettlementFrontier[]
636			),
637		});
638	}
639	
640	/**
641	 * Prepares a successor-authority-signed settlement checkpoint.
642	 * @param input - Exact close bindings, adjacent trusts and successor frontier.
643	 * @returns An opaque one-shot signing preparation or a fail-closed rejection.
644	 */
645	export function prepareCreatorAuthorSettlement(input: unknown): Readonly<
646		| { readonly ok: false; readonly reason: string }
647		| {
648				readonly digest: string;
649				readonly exactCanonicalPreimageBytes: Uint8Array;
650				readonly ok: true;
651				readonly preparation: CreatorAuthorSettlementPreparation;
652				readonly signingRequest: CreatorIssuanceRetirementSigningRequest;
653		  }
654	> {
655		try {
656			if (!plainRecord(input) || !exactKeys(input, SETTLEMENT_PREPARE_KEYS)) return failure("MALFORMED_INPUT");
657			const currentTrust = input.currentTrust as CurrentAnchorTrust;
658			const successorTrust = input.successorTrust as CurrentAnchorTrust;
659			const current = resolveCreatorAnchorTrustMaterial(currentTrust);
660			const successor = resolveCreatorAnchorTrustMaterial(successorTrust);
661			const frontiers = copiedSettlementFrontiers(input.frontiers);
662			if (
663				current === undefined ||
664				successor === undefined ||
665				frontiers === undefined ||
666				settlementProfileFor(currentTrust.profileId) !== "v1" ||
667				settlementProfileFor(successorTrust.profileId) !== "v1" ||
668				current.objectId !== successor.objectId ||
669				current.genesisAnchorDigest !== successor.genesisAnchorDigest ||
670				successor.currentEpoch !== current.currentEpoch + 1 ||
671				input.currentAclDigest !== anchorAclDigest(current.exactCanonicalCurrentAnchorPreimageBytes) ||
672				input.successorAclDigest !== anchorAclDigest(successor.exactCanonicalCurrentAnchorPreimageBytes)
673			) {
674				return failure("TRUST_INVALID");
675			}
676			const preimage = Object.freeze({
677				closedAnchorDigest: current.currentAnchorDigest,
678				closedEpoch: current.currentEpoch,
679				commitQcRef: plainRecord(input.commitQcRef)
680					? Object.freeze({ byteLength: input.commitQcRef.byteLength, digest: input.commitQcRef.digest })
681					: input.commitQcRef,
682				currentAclDigest: input.currentAclDigest,
683				cutValueDigest: input.cutValueDigest,
684				frontiers,
685				genesisAnchorDigest: current.genesisAnchorDigest,
686				historyRoot: input.historyRoot,
687				historySize: input.historySize,
688				kind: CREATOR_AUTHOR_SETTLEMENT_KIND,
689				objectId: current.objectId,
690				priorCheckpointDigest: input.priorCheckpointDigest,
691				priorCheckpointKind: input.priorCheckpointKind,
692				protocolMajor: 3,
693				snapshotManifestDigest: input.snapshotManifestDigest,
694				successorAclDigest: input.successorAclDigest,
695				successorAnchorDigest: successor.currentAnchorDigest,
696				successorEpoch: successor.currentEpoch,
697				version: 1,
698			});
699			if (!validSettlementRecordFields(preimage)) return failure("IDENTITY_INVALID");
700			const exactCanonicalPreimageBytes = encodeCanonical(preimage);
701			if (
702				encodeCanonical({ ...preimage, detachedAuthoritySignature: new Uint8Array(64) }).byteLength >
703				CREATOR_AUTHOR_SETTLEMENT_MAX_RECORD_BYTES
704			) {
705				return failure("RECORD_TOO_LARGE");
706			}
707			const digest = hashDomain(SETTLEMENT_DOMAIN, exactCanonicalPreimageBytes);
708			const preparation = Object.freeze({}) as CreatorAuthorSettlementPreparation;
709			settlementPreparations.set(
710				preparation,
711				Object.freeze({ digest: Uint8Array.from(digest), preimage, publicKey: Uint8Array.from(successor.publicKey) })
712			);
713			return Object.freeze({
714				digest: hex(digest),
715				exactCanonicalPreimageBytes: Uint8Array.from(exactCanonicalPreimageBytes),
716				ok: true as const,
717				preparation,
718				signingRequest: mintCreatorIssuanceRetirementSigningRequest(digest),
719			});
720		} catch {
721			return failure("MALFORMED_INPUT");
722		}
723	}
724	
725	/**
726	 * Completes and bounds a prepared settlement checkpoint.
727	 * @param input - Opaque preparation and detached successor-authority signature.
728	 * @returns Exact canonical record bytes or a fail-closed rejection.
729	 */
730	export function completeCreatorAuthorSettlement(
731		input: unknown
732	): Readonly<
733		| { readonly exactCanonicalRecordBytes: Uint8Array; readonly ok: true }
734		| { readonly ok: false; readonly reason: string }
735	> {
736		try {
737			if (!plainRecord(input) || !exactKeys(input, ["detachedSignature", "preparation"])) {
738				return failure("MALFORMED_INPUT");
739			}
740			const state = settlementPreparations.get(input.preparation as CreatorAuthorSettlementPreparation);
741			settlementPreparations.delete(input.preparation as CreatorAuthorSettlementPreparation);
742			if (state === undefined) return failure("PREPARATION_UNAVAILABLE");
743			if (!(input.detachedSignature instanceof Uint8Array) || input.detachedSignature.byteLength !== 64) {
744				return failure("SIGNATURE_INVALID");
745			}
746			const signature = Uint8Array.from(input.detachedSignature);
747			if (!ed25519.verify(signature, state.digest, state.publicKey, { zip215: false })) {
748				return failure("SIGNATURE_INVALID");
749			}
750			const exactCanonicalRecordBytes = encodeCanonical({
751				...state.preimage,
752				detachedAuthoritySignature: signature,
753			});
754			return exactCanonicalRecordBytes.byteLength > CREATOR_AUTHOR_SETTLEMENT_MAX_RECORD_BYTES
755				? failure("RECORD_TOO_LARGE")
756				: Object.freeze({ exactCanonicalRecordBytes: Uint8Array.from(exactCanonicalRecordBytes), ok: true as const });
757		} catch {
758			return failure("MALFORMED_INPUT");
759		}
760	}
761	
762	/**
763	 * Opens one exact settlement checkpoint using successor floor trust only.
764	 * @param input - Exact record bytes, expected bindings and successor floor trust.
765	 * @returns An opaque verified settlement capability or a fail-closed rejection.
766	 */
767	export function openCreatorAuthorSettlement(
768		input: unknown
769	): Readonly<
770		| { readonly capability: VerifiedCreatorAuthorSettlement; readonly ok: true }
771		| { readonly ok: false; readonly reason: string }
772	> {
773		try {
774			if (
775				!plainRecord(input) ||
776				!exactKeys(input, OPEN_KEYS) ||
777				!(input.exactCanonicalRecordBytes instanceof Uint8Array) ||
778				input.exactCanonicalRecordBytes.byteLength > CREATOR_AUTHOR_SETTLEMENT_MAX_RECORD_BYTES
779			) {
780				return failure("MALFORMED_INPUT");
781			}
782			const bytes = Uint8Array.from(input.exactCanonicalRecordBytes);
783			const decoded = decodeCanonical(bytes, {
