789				!plainRecord(decoded) ||
790				!exactKeys(decoded, SETTLEMENT_RECORD_KEYS) ||
791				compareBytes(encodeCanonical(decoded), bytes) !== 0 ||
792				!validSettlementRecordFields(decoded) ||
793				!(decoded.detachedAuthoritySignature instanceof Uint8Array)
794			) {
795				return failure("RECORD_INVALID");
796			}
797			const floorTrust = input.floorTrust as CurrentAnchorTrust;
798			const floor = resolveCreatorAnchorTrustMaterial(floorTrust);
799			const ref = decoded.commitQcRef as CreatorAuthorIssuanceFrontiersRef;
800			if (
801				floor === undefined ||
802				settlementProfileFor(floorTrust.profileId) !== "v1" ||
803				decoded.objectId !== floor.objectId ||
804				decoded.genesisAnchorDigest !== floor.genesisAnchorDigest ||
805				decoded.successorEpoch !== floor.currentEpoch ||
806				decoded.successorAnchorDigest !== floor.currentAnchorDigest ||
807				decoded.successorAclDigest !== anchorAclDigest(floor.exactCanonicalCurrentAnchorPreimageBytes) ||
808				decoded.currentAclDigest !== input.expectedCurrentAclDigest ||
809				decoded.successorAclDigest !== input.expectedSuccessorAclDigest ||
810				decoded.cutValueDigest !== input.expectedCutValueDigest ||
811				decoded.snapshotManifestDigest !== input.expectedSnapshotManifestDigest ||
812				!validRef(input.expectedCommitQcRef) ||
813				ref.byteLength !== input.expectedCommitQcRef.byteLength ||
814				ref.digest !== input.expectedCommitQcRef.digest
815			) {
816				return failure("IDENTITY_INVALID");
817			}
818			const { detachedAuthoritySignature: signature, ...preimage } = decoded;
819			const digest = hashDomain(SETTLEMENT_DOMAIN, encodeCanonical(preimage));
820			if (signature.byteLength !== 64 || !ed25519.verify(signature, digest, floor.publicKey, { zip215: false })) {
821				return failure("SIGNATURE_INVALID");
822			}
823			const capability = Object.freeze({}) as VerifiedCreatorAuthorSettlement;
824			verifiedSettlements.set(capability, settlementIdentity(decoded));
825			return Object.freeze({ capability, ok: true as const });
826		} catch {
827			return failure("MALFORMED_INPUT");
828		}
829	}
830	
831	/**
832	 * Resolves a detached identity from a genuine settlement capability.
833	 * @param capability - Capability returned by openCreatorAuthorSettlement.
834	 * @returns A detached frozen identity or undefined for foreign custody.
835	 */
836	export function resolveCreatorAuthorSettlement(
837		capability: VerifiedCreatorAuthorSettlement
838	): CreatorAuthorSettlementIdentity | undefined {
839		const selected = verifiedSettlements.get(capability);
840		return selected === undefined ? undefined : copiedSettlementIdentity(selected);
841	}
842	
843	/**
844	 * Returns a detached frontier for one author without exposing codec custody.
845	 * @param capability - Capability returned by openCreatorAuthorSettlement.
846	 * @param author - Lowercase author-key digest to select.
847	 * @returns A detached frontier or undefined when absent or foreign.
848	 */
849	export function frontierFor(
850		capability: VerifiedCreatorAuthorSettlement,
851		author: string
852	): CreatorAuthorSettlementFrontier | undefined {
853		const selected = verifiedSettlements.get(capability)?.frontiers.find((frontier) => frontier[0] === author);
854		return selected === undefined ? undefined : (Object.freeze([...selected]) as CreatorAuthorSettlementFrontier);
855	}
856	
857	/**
858	 * Returns the number of frontiers in a genuine settlement capability.
859	 * @param capability - Capability returned by openCreatorAuthorSettlement.
860	 * @returns The verified frontier count, or zero for foreign custody.
861	 */
862	export function frontierCount(capability: VerifiedCreatorAuthorSettlement): number {
863		return verifiedSettlements.get(capability)?.frontiers.length ?? 0;
864	}

