63	
64	function settlementMembers(value: unknown): readonly string[] | undefined {
65		if (value === null || typeof value !== "object" || Array.isArray(value)) return undefined;
66		const epoch = Reflect.get(value, "epoch");
67		const members = Reflect.get(value, "members");
68		if (
69			!Number.isSafeInteger(epoch) ||
70			(epoch as number) < 0 ||
71			!Array.isArray(members) ||
72			members.length < 1 ||
73			members.length > 256
74		) {
75			return undefined;
76		}
77		const authors: string[] = [];
78		let previous: string | undefined;
79		for (const member of members) {
80			if (member === null || typeof member !== "object" || Array.isArray(member)) return undefined;
81			const author = Reflect.get(member, "author");
82			if (
83				typeof author !== "string" ||
84				!/^[0-9a-f]{64}$/u.test(author) ||
85				(previous !== undefined && author <= previous)
86			) {
87				return undefined;
88			}
89			previous = author;
90			authors.push(author);
91		}
92		return Object.freeze(authors);
93	}
94	
95	function settlementFrontiers(value: unknown): readonly SettlementFrontier[] | undefined {
96		if (!Array.isArray(value) || value.length > 256) return undefined;
97		const output: SettlementFrontier[] = [];
98		let previous: string | undefined;
99		for (const entry of value) {
100			if (!Array.isArray(entry) || entry.length !== 3) return undefined;
101			const [author, admissionEpoch, terminalThrough] = entry;
102			if (
103				typeof author !== "string" ||
104				!/^[0-9a-f]{64}$/u.test(author) ||
105				(previous !== undefined && author <= previous) ||
106				!Number.isSafeInteger(admissionEpoch) ||
107				(admissionEpoch as number) < 0 ||
108				(terminalThrough !== null && (!Number.isSafeInteger(terminalThrough) || (terminalThrough as number) < 0))
109			) {
110				return undefined;
111			}
112			previous = author;
113			output.push(Object.freeze([author, admissionEpoch as number, terminalThrough as number | null]));
114		}
115		return Object.freeze(output);
116	}
