118	/**
119	 * Validates the bounded adjacency and ACL transition laws for one settlement checkpoint.
120	 * The checkpoint opener deliberately does not perform these predecessor-relative checks.
121	 * @param input - Opened current/successor ACLs and proposed/predecessor settlement identities.
122	 * @returns A fail-closed transition verdict.
123	 */
124	export function inspectCreatorAuthorSettlementAdvance(
125		input: unknown
126	): Readonly<{ readonly ok: true } | { readonly ok: false; readonly reason: string }> {
127		try {
128			if (SETTLEMENT_PROFILE !== "v1" || input === null || typeof input !== "object" || Array.isArray(input)) {
129				return Object.freeze({ ok: false, reason: "SETTLEMENT_ADVANCE_INVALID" });
130			}
131			const currentAcl = Reflect.get(input, "currentAcl");
132			const successorAcl = Reflect.get(input, "successorAcl");
133			const predecessor = Reflect.get(input, "predecessor");
134			const proposed = Reflect.get(input, "proposed");
135			if (proposed === null || typeof proposed !== "object" || Array.isArray(proposed)) {
136				return Object.freeze({ ok: false, reason: "SETTLEMENT_ADVANCE_INVALID" });
137			}
138			const currentMembers = settlementMembers(currentAcl);
139			const successorMembers = settlementMembers(successorAcl);
140			const proposedFrontiers = settlementFrontiers(Reflect.get(proposed, "frontiers"));
141			const currentEpoch = Reflect.get(currentAcl, "epoch");
142			const successorEpoch = Reflect.get(successorAcl, "epoch");
143			const closedEpoch = Reflect.get(proposed, "closedEpoch");
144			const proposedSuccessorEpoch = Reflect.get(proposed, "successorEpoch");
145			if (currentMembers === undefined || successorMembers === undefined || proposedFrontiers === undefined) {
146				return Object.freeze({ ok: false, reason: "SETTLEMENT_ADVANCE_SHAPE_INVALID" });
147			}
148			if (
149				closedEpoch !== currentEpoch ||
150				proposedSuccessorEpoch !== successorEpoch ||
151				!Number.isSafeInteger(closedEpoch) ||
152				(successorEpoch as number) !== (closedEpoch as number) + 1 ||
153				proposedFrontiers.length !== successorMembers.length ||
154				proposedFrontiers.some((frontier, index) => frontier[0] !== successorMembers[index])
155			) {
156				return Object.freeze({ ok: false, reason: "SETTLEMENT_ADVANCE_INVALID" });
157			}
158			const currentSet = new Set(currentMembers);
159			if (predecessor === null) {
160				if (closedEpoch !== 0 || Reflect.get(proposed, "priorCheckpointKind") !== "genesis") {
161					return Object.freeze({ ok: false, reason: "SETTLEMENT_ADVANCE_INVALID" });
162				}
163				for (const [author, admissionEpoch, terminalThrough] of proposedFrontiers) {
164					if (currentSet.has(author)) {
165						if (admissionEpoch !== 0) return Object.freeze({ ok: false, reason: "SETTLEMENT_ADVANCE_INVALID" });
166					} else if (admissionEpoch !== successorEpoch || terminalThrough !== null) {
167						return Object.freeze({ ok: false, reason: "SETTLEMENT_ADVANCE_INVALID" });
168					}
169				}
170				return Object.freeze({ ok: true });
171			}
172			if (predecessor === null || typeof predecessor !== "object" || Array.isArray(predecessor)) {
173				return Object.freeze({ ok: false, reason: "SETTLEMENT_ADVANCE_INVALID" });
174			}
175			const predecessorDigest = Reflect.get(predecessor, "candidateDigest");
176			const predecessorClosedEpoch = Reflect.get(predecessor, "closedEpoch");
177			const predecessorSuccessorEpoch = Reflect.get(predecessor, "successorEpoch");
178			const predecessorFrontiers = settlementFrontiers(Reflect.get(predecessor, "frontiers"));
179			if (
180				Reflect.get(proposed, "priorCheckpointKind") !== "settled-v1" ||
181				Reflect.get(proposed, "priorCheckpointDigest") !== predecessorDigest ||
182				typeof predecessorDigest !== "string" ||
183				!/^[0-9a-f]{64}$/u.test(predecessorDigest) ||
184				predecessorFrontiers === undefined ||
185				predecessorSuccessorEpoch !== closedEpoch ||
186				predecessorClosedEpoch !== (closedEpoch as number) - 1
187			) {
188				return Object.freeze({ ok: false, reason: "SETTLEMENT_ADVANCE_INVALID" });
189			}
190			const priorByAuthor = new Map(predecessorFrontiers.map((frontier) => [frontier[0], frontier]));
191			for (const [author, admissionEpoch, terminalThrough] of proposedFrontiers) {
192				if (!currentSet.has(author)) {
193					if (admissionEpoch !== successorEpoch || terminalThrough !== null) {
194						return Object.freeze({ ok: false, reason: "SETTLEMENT_ADVANCE_INVALID" });
195					}
196					continue;
197				}
198				const prior = priorByAuthor.get(author);
199				if (
200					prior === undefined ||
201					admissionEpoch !== prior[1] ||
202					(prior[2] !== null && (terminalThrough === null || terminalThrough < prior[2]))
203				) {
204					return Object.freeze({ ok: false, reason: "SETTLEMENT_ADVANCE_INVALID" });
205				}
206			}
207			return Object.freeze({ ok: true });
208		} catch {
209			return Object.freeze({ ok: false, reason: "SETTLEMENT_ADVANCE_INVALID" });
210		}
211	}
