213	function record(candidate: DetachedClosureCandidate): Readonly<Record<string, unknown>> | undefined {
214		try {
215			const decoded = decodeCanonical(candidate.bytes);
216			return decoded !== null && typeof decoded === "object" && !Array.isArray(decoded)
217				? (decoded as Readonly<Record<string, unknown>>)
218				: undefined;
219		} catch {
220			return undefined;
221		}
222	}
223	
224	function compareRef(left: GenerationRef, right: GenerationRef): number {
225		return left.digest < right.digest ? -1 : left.digest > right.digest ? 1 : 0;
226	}
227	
228	function uniqueCandidate(
229		candidates: readonly DetachedClosureCandidate[],
230		kind: string,
231		epoch: number,
232		phase?: string
233	): DetachedClosureCandidate | undefined {
234		const matches = candidates.filter((candidate) => {
235			const decoded = record(candidate);
236			return (
237				decoded?.kind === kind &&
238				(decoded.kind === "drp-anchor-trust-state" ? decoded.currentEpoch : decoded.epoch) === epoch &&
239				(phase === undefined || decoded.phase === phase)
240			);
241		});
242		return matches.length === 1 ? matches[0] : undefined;
243	}
244	
245	function failure(reason: string): InspectCreatorTransitionAdvanceResult {
246		return Object.freeze({ ok: false as const, reason });
247	}
248	
249	function sameRef(left: GenerationRef, right: GenerationRef): boolean {
250		return left.byteLength === right.byteLength && left.digest === right.digest;
251	}
252	
253	function exactCandidate(candidate: DetachedClosureCandidate): boolean {
254		const digest = digestBlob(candidate.bytes);
255		return digest.ok && digest.value === candidate.ref.digest && candidate.bytes.byteLength === candidate.ref.byteLength;
256	}
257	
258	function hex(bytes: Uint8Array): string {
259		return Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("");
260	}
261	
262	function retirementCandidates(closure: CreatorTransitionClosure): readonly DetachedClosureCandidate[] {
263		return closure.candidates.filter((candidate) => record(candidate)?.kind === CREATOR_ISSUANCE_RETIREMENT_KIND);
264	}
265	
266	function aggregateCandidates(closure: CreatorTransitionClosure): readonly DetachedClosureCandidate[] {
267		return closure.candidates.filter((candidate) => record(candidate)?.kind === CREATOR_AUTHOR_ISSUANCE_FRONTIERS_KIND);
268	}
269	
270	function exactClosureOccurrence(closure: readonly GenerationRef[], candidate: DetachedClosureCandidate): boolean {
271		return closure.filter((ref) => sameRef(ref, candidate.ref)).length === 1;
272	}
273	
274	function openedRetirement(
275		candidate: DetachedClosureCandidate,
276		floorTrust: CurrentAnchorTrust,
277		cut: DetachedClosureCandidate,
278		qc: DetachedClosureCandidate
279	):
280		| Readonly<{
281				readonly candidate: DetachedClosureCandidate;
282				readonly identity: CreatorIssuanceRetirementIdentity;
283		  }>
284		| undefined {
285		const decodedCut = record(cut);
286		if (
287			!exactCandidate(candidate) ||
288			!exactCandidate(cut) ||
289			!exactCandidate(qc) ||
290			typeof decodedCut?.snapshotManifestDigest !== "string"
291		) {
292			return undefined;
293		}
294		const opened = openCreatorIssuanceRetirement({
295			exactCanonicalRecordBytes: candidate.bytes,
296			expectedCommitQcRef: qc.ref,
297			expectedCutValueDigest: hex(hashDomain("ts-drp/hard-epoch-cut/v3", cut.bytes)),
298			expectedSnapshotManifestDigest: decodedCut.snapshotManifestDigest,
299			floorTrust,
300		});
301		if (!opened.ok) return undefined;
302		const identity = resolveCreatorIssuanceRetirement(opened.capability);
303		return identity === undefined ||
304			decodedCut.kind !== "drp-hard-epoch-cut" ||
305			decodedCut.objectId !== identity.objectId ||
306			decodedCut.epoch !== identity.closedEpoch ||
307			decodedCut.previousAnchor !== identity.closedAnchorDigest
308			? undefined
309			: Object.freeze({ candidate, identity });
310	}
