312	function openedAggregate(
313		candidate: DetachedClosureCandidate,
314		floorTrust: CurrentAnchorTrust,
315		cut: DetachedClosureCandidate,
316		qc: DetachedClosureCandidate,
317		currentAuthority: Readonly<{
318			readonly acl?: DetachedClosureCandidate;
319			readonly trust?: CurrentAnchorTrust;
320		}>
321	):
322		| Readonly<{
323				readonly candidate: DetachedClosureCandidate;
324				readonly identity: CreatorAuthorIssuanceFrontiersIdentity;
325		  }>
326		| undefined {
327		const decodedCut = record(cut);
328		const decodedAcl = currentAuthority.acl === undefined ? undefined : record(currentAuthority.acl);
329		const decodedAggregate = record(candidate);
330		if (
331			!exactCandidate(candidate) ||
332			!exactCandidate(cut) ||
333			!exactCandidate(qc) ||
334			(currentAuthority.acl !== undefined && !exactCandidate(currentAuthority.acl)) ||
335			typeof decodedCut?.snapshotManifestDigest !== "string" ||
336			(currentAuthority.acl === undefined
337				? currentAuthority.trust === undefined
338				: decodedAcl?.kind !== "drp-v3-latched-acl") ||
339			typeof decodedAggregate?.successorAclDigest !== "string"
340		) {
341			return undefined;
342		}
343		const expectedCurrentAclDigest =
344			currentAuthority.acl === undefined
345				? decodedAggregate.currentAclDigest
346				: hex(hashDomain("ts-drp/latched-acl/v3", currentAuthority.acl.bytes));
347		const opened = openCreatorAuthorIssuanceFrontiers({
348			...(currentAuthority.trust === undefined ? {} : { currentTrust: currentAuthority.trust }),
349			exactCanonicalRecordBytes: candidate.bytes,
350			expectedCommitQcRef: qc.ref,
351			expectedCurrentAclDigest,
352			expectedCutValueDigest: hex(hashDomain("ts-drp/hard-epoch-cut/v3", cut.bytes)),
353			expectedSnapshotManifestDigest: decodedCut.snapshotManifestDigest,
354			expectedSuccessorAclDigest: decodedAggregate.successorAclDigest,
355			floorTrust,
356		});
357		if (!opened.ok) return undefined;
358		const identity = resolveCreatorAuthorIssuanceFrontiers(opened.capability);
359		return identity === undefined ||
360			decodedCut.kind !== "drp-hard-epoch-cut" ||
361			decodedCut.objectId !== identity.objectId ||
362			decodedCut.epoch !== identity.closedEpoch ||
363			decodedCut.previousAnchor !== identity.closedAnchorDigest ||
364			(decodedAcl !== undefined &&
365				(decodedAcl.objectId !== identity.objectId || decodedAcl.epoch !== identity.closedEpoch))
366			? undefined
367			: Object.freeze({ candidate, identity });
368	}
