370	/**
371	 * Opens the sole retirement carrier in one authenticated successor generation.
372	 * The returned capability is private to the Node lifecycle and cannot be
373	 * manufactured from durable row bytes alone.
374	 * @param input - Exact successor closure and its independently authenticated floor.
375	 * @returns An opaque historical-issuance capability or undefined on any ambiguity.
376	 */
377	export function openVerifiedCreatorHistoricalIssuance(
378		input: Readonly<{
379			readonly author: string;
380			readonly closure: CreatorTransitionClosure;
381			readonly floorTrust: CurrentAnchorTrust;
382		}>
383	): VerifiedCreatorHistoricalIssuance | undefined {
384		try {
385			if (input.floorTrust.currentEpoch < 1) return undefined;
386			const closedEpoch = input.floorTrust.currentEpoch - 1;
387			const retirement = retirementCandidates(input.closure);
388			const aggregate = aggregateCandidates(input.closure);
389			const cut = uniqueCandidate(input.closure.candidates, "drp-hard-epoch-cut", closedEpoch);
390			const qc = uniqueCandidate(input.closure.candidates, "drp-seal-qc", closedEpoch, "commit");
391			const acl = uniqueCandidate(input.closure.candidates, "drp-v3-latched-acl", closedEpoch);
392			if (
393				retirement.length !== 1 ||
394				cut === undefined ||
395				qc === undefined ||
396				acl === undefined ||
397				!exactClosureOccurrence(input.closure.closure, retirement[0] as DetachedClosureCandidate)
398			) {
399				return undefined;
400			}
401			let selected: CreatorHistoricalIssuanceIdentity | undefined;
402			if (
403				aggregate.length === 1 &&
404				exactClosureOccurrence(input.closure.closure, aggregate[0] as DetachedClosureCandidate)
405			) {
406				const opened = openedAggregate(aggregate[0] as DetachedClosureCandidate, input.floorTrust, cut, qc, { acl });
407				const frontier = opened?.identity.frontiers.find(([author]) => author === input.author);
408				if (opened !== undefined && frontier !== undefined) {
409					selected = Object.freeze({
410						admittedAuthorSequence: frontier[1],
411						author: frontier[0],
412						closedAnchorDigest: opened.identity.closedAnchorDigest,
413						closedEpoch: opened.identity.closedEpoch,
414						objectId: opened.identity.objectId,
415						successorAnchorDigest: opened.identity.successorAnchorDigest,
416						successorEpoch: opened.identity.successorEpoch,
417					});
418				}
419			} else if (aggregate.length === 0) {
420				const opened = openedRetirement(retirement[0] as DetachedClosureCandidate, input.floorTrust, cut, qc);
421				if (opened !== undefined && opened.identity.author === input.author) {
422					selected = Object.freeze({
423						admittedAuthorSequence: opened.identity.admittedAuthorSequence,
424						author: opened.identity.author,
425						closedAnchorDigest: opened.identity.closedAnchorDigest,
426						closedEpoch: opened.identity.closedEpoch,
427						objectId: opened.identity.objectId,
428						successorAnchorDigest: opened.identity.successorAnchorDigest,
429						successorEpoch: opened.identity.successorEpoch,
430					});
431				}
432			}
433			if (
434				selected === undefined ||
435				selected.closedEpoch !== closedEpoch ||
436				selected.successorEpoch !== input.floorTrust.currentEpoch ||
437				selected.successorAnchorDigest !== input.floorTrust.currentAnchorDigest
438			) {
439				return undefined;
440			}
441			const capability = Object.freeze({}) as VerifiedCreatorHistoricalIssuance;
442			verifiedHistoricalIssuance.set(capability, selected);
443			return capability;
444		} catch {
445			return undefined;
446		}
447	}
