449	/**
450	 * Resolves a detached identity from a genuine Node-private capability.
451	 * @param capability - Capability returned by openVerifiedCreatorHistoricalIssuance.
452	 * @returns A detached frozen identity or undefined for foreign custody.
453	 */
454	export function resolveVerifiedCreatorHistoricalIssuance(
455		capability: VerifiedCreatorHistoricalIssuance
456	): CreatorHistoricalIssuanceIdentity | undefined {
