461	function authenticatedRetirementPair(input: InspectCreatorTransitionAdvanceInput):
462		| Readonly<{
463				readonly current?: DetachedClosureCandidate;
464				readonly currentIdentity?: CreatorIssuanceRetirementIdentity;
465				readonly proposed: DetachedClosureCandidate;
466				readonly proposedIdentity: CreatorIssuanceRetirementIdentity;
467		  }>
468		| undefined {
469		if (
470			input.currentTrust.currentEpoch < 0 ||
471			input.successorTrust.currentEpoch !== input.currentTrust.currentEpoch + 1 ||
472			input.currentTrust.objectId !== input.successorTrust.objectId ||
473			input.currentTrust.genesisAnchorDigest !== input.successorTrust.genesisAnchorDigest ||
474			input.proofRefs.length !== 2
475		) {
476			return undefined;
477		}
478		const currentMatches = retirementCandidates(input.current);
479		const proposedMatches = retirementCandidates(input.proposed);
480		if (proposedMatches.length !== 1 || currentMatches.length !== (input.currentTrust.currentEpoch === 0 ? 0 : 1)) {
481			return undefined;
482		}
483		const proposedRetirement = proposedMatches[0] as DetachedClosureCandidate;
484		if (!exactClosureOccurrence(input.proposed.closure, proposedRetirement)) return undefined;
485		if (
486			currentMatches.length === 1 &&
487			!exactClosureOccurrence(input.current.closure, currentMatches[0] as DetachedClosureCandidate)
488		) {
489			return undefined;
490		}
491		const proposedCut = input.proposed.candidates.find((candidate) =>
492			sameRef(candidate.ref, input.proofRefs[0] as GenerationRef)
493		);
494		const proposedQc = input.proposed.candidates.find((candidate) =>
495			sameRef(candidate.ref, input.proofRefs[1] as GenerationRef)
496		);
497		if (proposedCut === undefined || proposedQc === undefined) return undefined;
498		const openedProposed = openedRetirement(proposedRetirement, input.successorTrust, proposedCut, proposedQc);
499		if (
500			openedProposed === undefined ||
501			openedProposed.identity.closedEpoch !== input.currentTrust.currentEpoch ||
502			openedProposed.identity.closedAnchorDigest !== input.currentTrust.currentAnchorDigest
503		) {
504			return undefined;
505		}
506		if (input.currentTrust.currentEpoch === 0) {
507			return openedProposed.identity.priorAdmittedAuthorSequence === null &&
508				openedProposed.identity.priorRetirementCandidateDigest === CREATOR_ISSUANCE_RETIREMENT_GENESIS_SENTINEL
509				? Object.freeze({ proposed: openedProposed.candidate, proposedIdentity: openedProposed.identity })
510				: undefined;
511		}
512		const currentCandidate = currentMatches[0] as DetachedClosureCandidate;
513		const retiringCut = uniqueCandidate(
514			input.current.candidates,
515			"drp-hard-epoch-cut",
516			input.currentTrust.currentEpoch - 1
517		);
518		const retiringQc = uniqueCandidate(
519			input.current.candidates,
520			"drp-seal-qc",
521			input.currentTrust.currentEpoch - 1,
522			"commit"
523		);
524		if (retiringCut === undefined || retiringQc === undefined) return undefined;
525		const openedCurrent = openedRetirement(currentCandidate, input.currentTrust, retiringCut, retiringQc);
526		return openedCurrent !== undefined &&
527			openedProposed.identity.author === openedCurrent.identity.author &&
528			openedProposed.identity.priorRetirementCandidateDigest === currentCandidate.ref.digest &&
529			openedProposed.identity.priorAdmittedAuthorSequence === openedCurrent.identity.admittedAuthorSequence &&
530			openedProposed.identity.admittedAuthorSequence >= openedCurrent.identity.admittedAuthorSequence
531			? Object.freeze({
532					current: currentCandidate,
533					currentIdentity: openedCurrent.identity,
534					proposed: openedProposed.candidate,
535					proposedIdentity: openedProposed.identity,
536				})
537			: undefined;
538	}
