540	function authenticatedAggregatePair(
541		input: InspectCreatorTransitionAdvanceInput,
542		retirement: NonNullable<ReturnType<typeof authenticatedRetirementPair>>
543	):
544		| Readonly<{
545				readonly current?: DetachedClosureCandidate;
546				readonly proposed: DetachedClosureCandidate;
547		  }>
548		| undefined {
549		const currentMatches = aggregateCandidates(input.current);
550		const proposedMatches = aggregateCandidates(input.proposed);
551		if (currentMatches.length > 1 || proposedMatches.length !== 1) return undefined;
552		const proposed = proposedMatches[0] as DetachedClosureCandidate;
553		if (!exactClosureOccurrence(input.proposed.closure, proposed)) return undefined;
554		const proposedCut = input.proposed.candidates.find((candidate) =>
555			sameRef(candidate.ref, input.proofRefs[0] as GenerationRef)
556		);
557		const proposedQc = input.proposed.candidates.find((candidate) =>
558			sameRef(candidate.ref, input.proofRefs[1] as GenerationRef)
559		);
560		if (proposedCut === undefined || proposedQc === undefined) return undefined;
561		const openedProposed = openedAggregate(proposed, input.successorTrust, proposedCut, proposedQc, {
562			trust: input.currentTrust,
563		});
564		if (
565			openedProposed === undefined ||
566			openedProposed.identity.closedEpoch !== input.currentTrust.currentEpoch ||
567			openedProposed.identity.closedAnchorDigest !== input.currentTrust.currentAnchorDigest
568		) {
569			return undefined;
570		}
571		const legacyFrontier = openedProposed.identity.frontiers.find(
572			([author]) => author === retirement.proposedIdentity.author
573		);
574		if (legacyFrontier !== undefined && legacyFrontier[1] !== retirement.proposedIdentity.admittedAuthorSequence) {
575			return undefined;
576		}
577		if (currentMatches.length === 0) {
578			return openedProposed.identity.priorAggregateCandidateDigest === CREATOR_AUTHOR_ISSUANCE_FRONTIERS_GENESIS_SENTINEL
579				? Object.freeze({ proposed })
580				: undefined;
581		}
582		const current = currentMatches[0] as DetachedClosureCandidate;
583		if (!exactClosureOccurrence(input.current.closure, current)) return undefined;
584		const closedEpoch = input.currentTrust.currentEpoch - 1;
585		const currentCut = uniqueCandidate(input.current.candidates, "drp-hard-epoch-cut", closedEpoch);
586		const currentQc = uniqueCandidate(input.current.candidates, "drp-seal-qc", closedEpoch, "commit");
587		const currentAcl = uniqueCandidate(input.current.candidates, "drp-v3-latched-acl", closedEpoch);
588		if (currentCut === undefined || currentQc === undefined || currentAcl === undefined) return undefined;
589		const openedCurrent = openedAggregate(current, input.currentTrust, currentCut, currentQc, { acl: currentAcl });
590		if (openedCurrent === undefined || openedProposed.identity.priorAggregateCandidateDigest !== current.ref.digest) {
591			return undefined;
592		}
593		const proposedByAuthor = new Map(openedProposed.identity.frontiers);
594		for (const [author, boundary] of openedCurrent.identity.frontiers) {
595			const next = proposedByAuthor.get(author);
596			if (next !== undefined && boundary !== null && (next === null || next < boundary)) return undefined;
597		}
598		return Object.freeze({ current, proposed });
