601	/**
602	 * Selects the compatibility or bounded transition predicate and owns stale-ref derivation.
603	 * @param input - Current/proposed closure pair, new proof refs, and staging/verification mode.
604	 * @returns The authenticated proposal (normalized only for in-memory staging) or a rejection.
605	 */
606	export function inspectCreatorTransitionAdvance(
607		input: InspectCreatorTransitionAdvanceInput
608	): InspectCreatorTransitionAdvanceResult {
609		try {
610			const retirement = authenticatedRetirementPair(input);
611			if (retirement === undefined) return failure("TRUST_CLOSURE_INVALID");
612			const aggregate = authenticatedAggregatePair(input, retirement);
613			if (aggregate === undefined) return failure("TRUST_CLOSURE_INVALID");
614			const withoutControlCandidates = (
615				closure: CreatorTransitionClosure,
616				candidates: readonly (DetachedClosureCandidate | undefined)[]
617			): CreatorTransitionClosure =>
618				Object.freeze({
619					candidates: Object.freeze(
620						closure.candidates.filter(
621							(item) => !candidates.some((candidate) => candidate !== undefined && sameRef(item.ref, candidate.ref))
622						)
623					),
624					closure: Object.freeze(
625						closure.closure.filter(
626							(ref) => !candidates.some((candidate) => candidate !== undefined && sameRef(ref, candidate.ref))
627						)
628					),
629				});
630			const normalizedCurrent = withoutControlCandidates(input.current, [retirement.current, aggregate.current]);
631			const normalizedProposed = withoutControlCandidates(input.proposed, [retirement.proposed, aggregate.proposed]);
632			const trustCandidates = input.current.candidates.filter(
633				(candidate) => record(candidate)?.kind === "drp-anchor-trust-state"
634			);
635			if (trustCandidates.length !== 1) return failure("TRUST_CLOSURE_INVALID");
636			const trust = record(trustCandidates[0] as DetachedClosureCandidate);
637			if (typeof trust?.currentEpoch !== "number" || !Number.isSafeInteger(trust.currentEpoch)) {
638				return failure("TRUST_CLOSURE_INVALID");
639			}
640			if (trust.currentEpoch === 0) {
641				const result = inspectCreatorTrustAdvance({
642					current: normalizedCurrent,
643					proofRefs: input.proofRefs,
644					proposed: normalizedProposed,
645				});
646				return result.ok
647					? Object.freeze({ kind: result.kind, ok: true as const, proposed: input.proposed })
648					: failure(result.reason);
649			}
650			const retiringEpoch = trust.currentEpoch - 1;
651			const retiringCut = uniqueCandidate(input.current.candidates, "drp-hard-epoch-cut", retiringEpoch);
652			const retiringQc = uniqueCandidate(input.current.candidates, "drp-seal-qc", retiringEpoch, "commit");
653			const retiringAcl = uniqueCandidate(input.current.candidates, "drp-v3-latched-acl", retiringEpoch);
654			if (retiringCut === undefined || retiringQc === undefined || retiringAcl === undefined) {
655				return failure("RETIRING_PROOF_REFS_INVALID");
656			}
657			const retiring = new Set([retiringCut.ref.digest, retiringQc.ref.digest, retiringAcl.ref.digest]);
658			const proposedWithoutRetiring =
659				input.mode === "stage"
660					? Object.freeze({
661							candidates: Object.freeze(
662								normalizedProposed.candidates.filter((candidate) => !retiring.has(candidate.ref.digest))
663							),
664							closure: Object.freeze(
665								normalizedProposed.closure.filter((ref) => !retiring.has(ref.digest)).sort(compareRef)
666							),
667						})
668					: normalizedProposed;
669			const result = inspectBoundedCreatorTrustAdvance({
670				current: normalizedCurrent,
671				proofRefs: input.proofRefs,
672				proposed: proposedWithoutRetiring,
673				retiringPredecessorAclRef: retiringAcl.ref,
674				retiringProofRefs: [retiringCut.ref, retiringQc.ref],
675			});
676			if (!result.ok) return failure(result.reason);
677			const proposed =
678				input.mode === "verify"
679					? input.proposed
680					: Object.freeze({
681							candidates: Object.freeze(
682								[...proposedWithoutRetiring.candidates, retirement.proposed, aggregate.proposed].sort((left, right) =>
683									compareRef(left.ref, right.ref)
684								)
685							),
686							closure: Object.freeze(
687								[...proposedWithoutRetiring.closure, retirement.proposed.ref, aggregate.proposed.ref].sort(compareRef)
688							),
689						});
690			return Object.freeze({ kind: result.kind, ok: true as const, proposed });
691		} catch {
692			return failure("TRUST_CLOSURE_INVALID");
693		}
694	}

