330	function aclSnapshot(version: 1 | 2 | 3, count: number, full = false): Readonly<Record<string, unknown>> {
331		const members = Array.from({ length: count }, (_, index) =>
332			aclMember(index.toString(16).padStart(64, "0"), version, full)
333		);
334		if (!members.some((member) => (member.groups as readonly string[]).includes("admin"))) {
335			members[0] = aclMember("0".repeat(64), version, true);
336		}
337		return Object.freeze({
338			epoch: 8,
339			kind: "drp-v3-latched-acl",
340			members: Object.freeze(members),
341			objectId: OBJECT_ID,
342			permissionless: false,
343			version,
344		});
345	}
