175				if (typeof valueGroup !== "string" || !groupsForSnapshot.includes(valueGroup as LatchedAclGroup)) {
176					return undefined;
177				}
178				const index = groupsForSnapshot.indexOf(valueGroup as LatchedAclGroup);
179				if (index <= previousGroup) return undefined;
180				previousGroup = index;
181				groups.push(valueGroup as LatchedAclGroup);
182			}
183			if (version === 1 && groups.includes("referee") && groups.join(",") !== GROUPS_V2.join(",")) return undefined;
184			if (selected.finalityKey !== null && !groups.includes("finality")) return undefined;
185			previousAuthor = selected.author;
186			members.push(
187				Object.freeze({
188					author: selected.author,
189					finalityKey: selected.finalityKey,
190					groups: Object.freeze(groups),
191				})
192			);
193		}
194		if (!members.some(({ groups }) => groups.includes("admin"))) return undefined;
195		const snapshot = Object.freeze({
196			epoch: record.epoch,
197			kind: "drp-v3-latched-acl",
198			members: Object.freeze(members),
199			objectId: record.objectId,
200			permissionless: record.permissionless,
201			version,
202		});
203		openedSnapshots.set(
204			snapshot,
205			Object.freeze({ membersByAuthor: new Map(members.map((member) => [member.author, member])) })
206		);
207		return snapshot;
208	}
209	
210	/**
211	 * Opens one canonical current-epoch ACL snapshot against anchor-bound identity.
212	 * @param input - Exact carrier bytes and the authenticated anchor expectations.
213	 * @returns A detached snapshot or a closed fail-closed result.
214	 */
215	export function openCanonicalLatchedAclSnapshot(
216		input: Readonly<{
217			readonly exactCanonicalLatchedAclBytes: Uint8Array;
218			readonly expectedAclDigest: string;
219			readonly expectedEpoch: number;
220			readonly expectedObjectId: string;
221			readonly expectedProfileId?: string;
222		}>
223	): OpenCanonicalLatchedAclResult {
224		try {
225			const record = exactDataRecord(input, OPEN_KEYS) ?? exactDataRecord(input, OPEN_KEYS_WITH_PROFILE);
226			const settlementProfile =
227				record !== undefined && typeof record.expectedProfileId === "string"
228					? settlementProfileFor(record.expectedProfileId)
229					: "none";
230			const maximumBytes = settlementProfile === "v1" ? SETTLEMENT_MAX_CANONICAL_BYTES : MAX_CANONICAL_BYTES;
231			if (
232				record === undefined ||
233				!(record.exactCanonicalLatchedAclBytes instanceof Uint8Array) ||
234				record.exactCanonicalLatchedAclBytes.byteLength === 0 ||
235				record.exactCanonicalLatchedAclBytes.byteLength > maximumBytes ||
236				typeof record.expectedAclDigest !== "string" ||
237				!DIGEST.test(record.expectedAclDigest) ||
238				typeof record.expectedEpoch !== "number" ||
239				!Number.isSafeInteger(record.expectedEpoch) ||
240				record.expectedEpoch < 0 ||
241				typeof record.expectedObjectId !== "string" ||
242				!OBJECT_ID.test(record.expectedObjectId)
243			) {
244				return Object.freeze({ ok: false, reason: "malformed-input" });
245			}
246			const exactBytes = new Uint8Array(record.exactCanonicalLatchedAclBytes);
247			const decoded = decodeCanonical(
248				exactBytes,
249				settlementProfile === "v1"
250					? { maxBytes: SETTLEMENT_MAX_CANONICAL_BYTES, maxDepth: 4, maxItems: SETTLEMENT_MAX_CANONICAL_ITEMS }
251					: { maxBytes: MAX_CANONICAL_BYTES, maxDepth: 4, maxItems: MAX_CANONICAL_ITEMS }
252			);
253			if (!sameBytes(encodeCanonical(decoded), exactBytes)) {
254				return Object.freeze({ ok: false, reason: "malformed-input" });
255			}
256			const snapshot = copySnapshot(decoded);
257			if (
258				snapshot === undefined ||
259				(snapshot.version === 3) !== (settlementProfile === "v1") ||
260				snapshot.epoch !== record.expectedEpoch ||
261				snapshot.objectId !== record.expectedObjectId ||
262				lowerHex(hashDomain("ts-drp/latched-acl/v3", exactBytes)) !== record.expectedAclDigest
263			) {
264				return Object.freeze({ ok: false, reason: "snapshot-mismatch" });
265			}
266			return Object.freeze({ ok: true, snapshot });
267		} catch {
268			return Object.freeze({ ok: false, reason: "malformed-input" });
269		}
270	}
271	
272	function mutableMembers(snapshot: LatchedAclSnapshot): Map<string, MutableMember> {
273		return new Map(
274			snapshot.members.map(({ author, finalityKey, groups }) => [
275				author,
276				{ author, finalityKey, groups: new Set(groups) },
277			])
278		);
279	}
280	
281	function copyOperation(value: unknown, version: LatchedAclSnapshot["version"]): LatchedAclOperation | undefined {
282		if (typeof value !== "object" || value === null) return undefined;
283		const kindDescriptor = Object.getOwnPropertyDescriptor(value, "kind");
284		if (kindDescriptor === undefined || !("value" in kindDescriptor)) return undefined;
285		if (kindDescriptor.value === "set-finality-key") {
286			const record = exactDataRecord(value, SET_KEY_KEYS);
287			if (
288				record === undefined ||
289				record.kind !== "set-finality-key" ||
290				typeof record.actor !== "string" ||
291				!AUTHOR.test(record.actor) ||
292				typeof record.finalityKey !== "string" ||
293				!AUTHOR.test(record.finalityKey)
294			) {
295				return undefined;
296			}
297			return Object.freeze({ actor: record.actor, finalityKey: record.finalityKey, kind: "set-finality-key" });
298		}
299		const record = exactDataRecord(value, GRANT_REVOKE_KEYS);
300		if (
301			record === undefined ||
302			(record.kind !== "grant" && record.kind !== "revoke") ||
303			typeof record.actor !== "string" ||
304			!AUTHOR.test(record.actor) ||
305			typeof record.target !== "string" ||
306			!AUTHOR.test(record.target) ||
307			!isGroup(record.group, version)
308		) {
309			return undefined;
310		}
311		return Object.freeze({ actor: record.actor, group: record.group, kind: record.kind, target: record.target });
312	}
313	
314	function authorityInput(value: unknown):
315		| Readonly<{
316				author: string;
317				membersByAuthor: ReadonlyMap<string, LatchedAclMember>;
318				snapshot: LatchedAclSnapshot;
319		  }>
320		| undefined {
321		const record = exactDataRecord(value, AUTHORITY_INPUT_KEYS);
322		const snapshot = record === undefined ? undefined : copySnapshot(record.snapshot);
323		const state = snapshot === undefined ? undefined : openedSnapshots.get(snapshot);
324		if (
325			record === undefined ||
326			snapshot === undefined ||
327			state === undefined ||
328			typeof record.author !== "string" ||
329			!AUTHOR.test(record.author)
330		) {
331			return undefined;
332		}
333		return Object.freeze({ author: record.author, membersByAuthor: state.membersByAuthor, snapshot });
334	}
335	
336	function authorityFailure(): LatchedAclAuthorityResult {
337		return Object.freeze({ ok: false, reason: "malformed-input" });
338	}
339	
340	/**
341	 * Determines whether an already-authenticated author belongs to the latched epoch ACL.
342	 * @param input - Candidate author and validated current-epoch snapshot.
343	 * @returns A fail-closed authority decision.
344	 */
345	export function authorizeLatchedEnvelopeAuthor(
346		input: Readonly<{
347			readonly author: string;
348			readonly snapshot: LatchedAclSnapshot;
349		}>
350	): LatchedAclAuthorityResult {
351		try {
352			const selected = authorityInput(input);
353			if (selected === undefined) return authorityFailure();
354			return Object.freeze({
355				authorized: selected.membersByAuthor.has(selected.author),
356				ok: true,
357			});
358		} catch {
359			return authorityFailure();
360		}
361	}
362	
363	/**
364	 * Determines whether an admitted author may execute an application write in the latched epoch.
365	 * @param input - Candidate author and validated current-epoch snapshot.
366	 * @returns A fail-closed application-writer decision.
367	 */
368	export function authorizeLatchedApplicationWrite(
369		input: Readonly<{
370			readonly author: string;
371			readonly snapshot: LatchedAclSnapshot;
372		}>
373	): LatchedAclAuthorityResult {
374		try {
375			const selected = authorityInput(input);
376			if (selected === undefined) return authorityFailure();
377			const member = selected.membersByAuthor.get(selected.author);
378			return Object.freeze({
379				authorized: member !== undefined && (selected.snapshot.permissionless || member.groups.includes("writer")),
380				ok: true,
381			});
382		} catch {
383			return authorityFailure();
384		}
385	}
386	
387	function failedStage(
388		index: number,
389		reason: "last-admin" | "malformed-input" | "operation-invalid" | "operation-not-authorized"
390	): StageLatchedAclResult {
391		return Object.freeze({ index, ok: false, reason });
392	}
393	
394	function freezeMembers(
395		members: Map<string, MutableMember>,
396		version: LatchedAclSnapshot["version"]
397	): readonly LatchedAclMember[] {
398		return Object.freeze(
399			[...members.values()]
400				.filter(({ finalityKey, groups }) => groups.size > 0 || finalityKey !== null)
401				.sort((left, right) => compareText(left.author, right.author))
402				.map(({ author, finalityKey, groups }) =>
403					Object.freeze({
404						author,
405						finalityKey,
406						groups: Object.freeze(
407							[...groups].sort(
408								(left, right) =>
409									snapshotGroupsForVersion(version).indexOf(left) - snapshotGroupsForVersion(version).indexOf(right)
410							)
411						),
412					})
413				)
414		);
415	}
416	
417	/**
418	 * Applies authorized ACL operations to an isolated next-epoch snapshot.
419	 * @param input - Latched snapshot and canonically ordered candidate operations.
420	 * @returns The detached next snapshot or the first fail-closed rejection.
421	 */
422	export function stageLatchedAclOperations(
423		input: Readonly<{
424			readonly operations: readonly LatchedAclOperation[];
425			readonly snapshot: LatchedAclSnapshot;
426		}>
427	): StageLatchedAclResult {
428		try {
429			const record = exactDataRecord(input, STAGE_INPUT_KEYS);
430			const snapshot = record === undefined ? undefined : copySnapshot(record.snapshot);
431			if (record === undefined || snapshot === undefined || !Array.isArray(record.operations)) {
432				return failedStage(0, "malformed-input");
433			}
434			const operations: LatchedAclOperation[] = [];
435			for (const [index, value] of record.operations.entries()) {
436				const operation = copyOperation(value, snapshot.version);
437				if (operation === undefined) return failedStage(index, "malformed-input");
438				operations.push(operation);
439			}
440			const latched = mutableMembers(snapshot);
441			for (const [index, operation] of operations.entries()) {
442				const actor = latched.get(operation.actor);
443				if (operation.kind === "set-finality-key") {
444					if (!actor?.groups.has("finality")) return failedStage(index, "operation-not-authorized");
445				} else {
446					if (!actor?.groups.has("admin")) return failedStage(index, "operation-not-authorized");
447					if (snapshot.permissionless && operation.group === "writer") {
448						return failedStage(index, "operation-invalid");
449					}
450				}
451			}
452	
453			const nextMembers = mutableMembers(snapshot);
454			for (const operation of operations) {
455				if (operation.kind !== "grant") continue;
456				const target = nextMembers.get(operation.target) ?? {
457					author: operation.target,
458					finalityKey: null,
459					groups: new Set<LatchedAclGroup>(),
460				};
461				target.groups.add(operation.group);
462				nextMembers.set(operation.target, target);
463			}
464			for (const operation of operations) {
465				if (operation.kind !== "set-finality-key") continue;
466				const actor = nextMembers.get(operation.actor);
467				if (actor === undefined) return failedStage(0, "operation-invalid");
468				actor.finalityKey = operation.finalityKey;
469			}
470			for (const operation of operations) {
471				if (operation.kind !== "revoke") continue;
472				const target = nextMembers.get(operation.target);
473				target?.groups.delete(operation.group);
474				if (target !== undefined && operation.group === "finality") target.finalityKey = null;
475			}
476			const frozenMembers = freezeMembers(nextMembers, snapshot.version);
477			if (!frozenMembers.some(({ groups }) => groups.includes("admin"))) {
478				const index = operations.findIndex((operation) => operation.kind === "revoke" && operation.group === "admin");
479				return failedStage(Math.max(0, index), "last-admin");
480			}
481			if (snapshot.epoch === Number.MAX_SAFE_INTEGER) {
482				return failedStage(0, "operation-invalid");
483			}
484			const next = copySnapshot(
485				Object.freeze({
486					epoch: snapshot.epoch + 1,
487					kind: "drp-v3-latched-acl",
488					members: frozenMembers,
489					objectId: snapshot.objectId,
490					permissionless: snapshot.permissionless,
491					version: snapshot.version,
492				})
493			);
494			if (next === undefined) return failedStage(0, "operation-invalid");
495			const settlement = next.version === 3;
496			const exactBytes = encodeCanonical(next);
497			const maximumBytes = settlement ? SETTLEMENT_MAX_CANONICAL_BYTES : MAX_CANONICAL_BYTES;
498			if (exactBytes.byteLength > maximumBytes) return failedStage(0, "operation-invalid");
499			decodeCanonical(exactBytes, {
500				maxBytes: maximumBytes,
501				maxDepth: 4,
502				maxItems: settlement ? SETTLEMENT_MAX_CANONICAL_ITEMS : MAX_CANONICAL_ITEMS,
503			});
504			return Object.freeze({ next, ok: true });
505		} catch {
506			return failedStage(0, "malformed-input");
507		}
508	}
