510	/**
511	 * Derives the ordered next-epoch seal signer set from a validated ACL snapshot.
512	 * @param input - Candidate next-epoch ACL snapshot.
513	 * @returns The sorted signer set or a malformed-input rejection.
514	 */
515	export function deriveNextLatchedSignerSet(
516		input: Readonly<{
517			readonly snapshot: LatchedAclSnapshot;
518		}>
519	): DeriveLatchedSignerSetResult {
520		try {
521			const record = exactDataRecord(input, SIGNER_INPUT_KEYS);
522			const snapshot = record === undefined ? undefined : copySnapshot(record.snapshot);
523			if (snapshot === undefined) return Object.freeze({ ok: false, reason: "malformed-input" });
524			return Object.freeze({
525				ok: true,
526				signers: Object.freeze(
527					snapshot.members.flatMap(({ author, finalityKey, groups }) =>
528						groups.includes("finality") && finalityKey !== null
529							? [Object.freeze({ publicKey: finalityKey, signerId: author })]
530							: []
531					)
532				),
533			});
534		} catch {
535			return Object.freeze({ ok: false, reason: "malformed-input" });
536		}
537	}
